const d0 = jsonData.directive_interpretation[0];
pm.expect(d0.note_index).to.eql(0);
pm.expect(d0.applies).to.eql(true);
pm.expect(d0.directive_type).to.eql('solar_reduction');
pm.expect(d0.structured_adjustment.hours).to.eql([12, 13]);
pm.expect(d0.structured_adjustment.factor).to.be.closeTo(0.25, 0.01);
const d1 = jsonData.directive_interpretation[1];
pm.expect(d1.note_index).to.eql(1);
pm.expect(d1.applies).to.eql(false);
pm.expect(d1.directive_type).to.eql('no_op');
pm.expect(d1.structured_adjustment).to.be.null;

